    input  a,
    input  b,
    input  c,
    input  d,
    output out_sop,
    output out_pos
);
    wire w0 = ~(a & b & c & d);
    wire w1 = ~(a & b & ~c & ~d);
    wire w2 = ~(a & ~b & c & ~d);
    wire w3 = ~(~a & b & c & ~d);
    wire w4 = ~(a & b & ~c & d);
    wire w5 = ~(a & ~b & ~c & ~d);
    wire w6 = ~(~a & b & ~c & d);
    wire w7 = ~(a & b & c & d);
    wire w8 = ~(a & ~b & c & d);
    wire w9 = ~(~a & b & ~c & ~d);
    wire w10 = ~(a & b & ~c & ~d);
    wire w11 = ~(a & ~b & ~c & d);
    wire w12 = ~(~a & b & d & ~c);
    wire w13 = ~(a & b & ~c & ~d);
    wire w14 = ~(a & ~b & c & ~d);
    wire w15 = ~(~a & b & c & d);
    assign out_sop = w0 | w7 | w15;
    assign out_pos = ~(w0 & w7 & w15 & w1 & w2 & w3 & w4 & w5 & w6 & w8 & w9 & w10 & w11 & w12 & w13 & w14);
endmodule

